function videoFor(id){const x=moves[id];if(videoDemos[x[0]])return videoDemos[x[0]];const teacher=x[1]==='Yoga & mobility'?'Yoga With Adriene':x[1].startsWith('Heels')?'STEEZY Shaka Lee':x[1]==='Cardio'?'NHS low impact cardio': 'physiotherapist exercise demonstration';const query=x[0]+' '+teacher+' tutorial';return {url:'https://www.youtube.com/results?search_query='+encodeURIComponent(query),label:'Find a video demonstration',type:'video_search',note:'Opens video search results; an exact demonstration has not been verified.'};}
function videoLink(id){const v=videoFor(id);return `<div class="video-link"><a href="${v.url}" target="_blank" rel="noopener noreferrer">▶ ${v.label} ↗</a><p class="small muted">${v.note||'Instructor video page. Use the comfortable variation in Forma.'}</p></div>`;}


const goalLabels={mobility:'Mobility',posture:'Posture',tone:'Muscle definition',dance:'Dance technique',endurance:'Cardio fitness',balance:'Balance'};
const defaultProfile={goals:['mobility','posture','tone'],primary:'mobility',minutes:25,intensity:'steady',equipment:'both',floor:true,cardioMinutes:20};
if(!state.profile)state.profile={...defaultProfile,goals:[...defaultProfile.goals]};
if(!state.checkins)state.checkins=[];
let goalDraft=null;
function goalPlan(profile){const allowed=['bodyweight','bands','weights','both'];const equipment=allowed.includes(profile.equipment)?profile.equipment:'both';const goals=[...new Set(profile.goals||[])].filter(g=>goalLabels[g]);const primary=goals.includes(profile.primary)?profile.primary:goals[0]||'mobility';const floor=profile.floor!==false;const resistance=equipment!=='bodyweight';const hasWeights=equipment==='weights'||equipment==='both';let strength=[hasWeights&&floor?'Dumbbell floor press':'Wall push-up',resistance?'Band or dumbbell row':'Shoulder-blade squeeze','Glute bridge','Chair squat',floor?'Heel slide':'Standing hip extension'];
if(resistance)strength.push('Biceps curl','Triceps kickback');else strength.push(floor?'Bird dog':'Wall sit with arm variations');
if(goals.includes('posture'))strength.push('Shoulder-blade squeeze');if(goals.includes('tone')&&floor)strength.push('Bird dog');if(primary==='tone'&&floor)strength=strength.map(n=>n==='Glute bridge'?'Hip thrust':n);
if(!floor)strength=strength.map(n=>n==='Glute bridge'?'Standing hip extension':n);
strength=[...new Set(strength)];const limit=profile.minutes===15?6:profile.minutes===35?10:8;strength=strength.slice(0,limit);
let yoga=primary==='posture'?['Cat–cow','Thread the needle','Eagle arms stretch','Supported chest opener','Child’s pose','Easy seat / lotus option']:['Cat–cow','Thread the needle','Low lunge','Butterfly pose','Child’s pose','Easy seat / lotus option'];
if(!floor)yoga=['Standing side bend','Eagle arms stretch','Warrior I','Warrior II','Easy seat / lotus option'];
if(primary==='balance'&&floor)yoga=['Cat–cow','Warrior I','Warrior II','Standing side bend','Butterfly pose','Easy seat / lotus option'];if(primary==='dance'&&floor)yoga=['Cat–cow','Low lunge','Butterfly pose','Eagle arms stretch','Child’s pose','Easy seat / lotus option'];if(primary==='endurance')yoga=yoga.slice(0,3);if(profile.minutes===15)yoga=yoga.slice(0,3);if(profile.minutes===35&&floor)yoga.push('Supported chest opener','Knees to chest');yoga=[...new Set(yoga)];
const sets=profile.intensity==='gentle'?1:profile.intensity==='progressive'?3:2;
return {goals,primary,equipment,minutes:profile.minutes,sets,strength,yoga,cardioMinutes:profile.cardioMinutes||20,why:[goals.includes('mobility')?'Mobility: comfortable hip and upper-back movement, with smaller ranges available.':null,goals.includes('posture')?'Posture: upper-back control, pulling work, chest opening, and trunk stability.':null,goals.includes('tone')?'Muscle definition: repeatable resistance work for chest, glutes, abs, and arms; build gradually.':null,goals.includes('dance')?'Dance: keep fundamentals before the rotating advanced extension.':null,goals.includes('endurance')?'Cardio fitness: two scheduled cardio sessions with an editable duration.':null,goals.includes('balance')?'Balance: controlled standing work and supported dance weight transfers.':null].filter(Boolean)};
}
function applyGoalPlan(profile,announce=true){state.profile={...profile,goals:[...profile.goals]};const plan=goalPlan(state.profile);state.profile.primary=plan.primary;state.routine=plan.strength;state.duration=profile.minutes;state.equipment=profile.equipment==='bodyweight'?'bodyweight':'weights';state.goal=2;state.profileApplied=true;state.customRoutine=false;save();render();if(announce)toast(saved?'Your goal-based plan is ready.':'Plan updated for this visit only.');}
function goalYogaNames(){return goalPlan(state.profile).yoga;}
function profileFromForm(){return {goals:Object.keys(goalLabels).filter(g=>$('#goal-'+g).checked),primary:$('#primaryGoal').value,minutes:Number($('#profileMinutes').value),intensity:$('#profileIntensity').value,equipment:$('#profileEquipment').value,floor:$('#profileFloor').checked,cardioMinutes:Number($('#profileCardio').value)};}
function previewGoals(){goalDraft=profileFromForm();if(!goalDraft.goals.length){$('#planPreview').innerHTML='<p>Choose at least one goal to preview your plan.</p>';$('#applyGoals').disabled=true;return}const plan=goalPlan(goalDraft);$('#applyGoals').disabled=false;$('#planPreview').innerHTML=`<div class="eyebrow">RECOMMENDATION · READY TO REVIEW</div><h2>${goalLabels[plan.primary]} comes first.</h2><p>${plan.goals.map(g=>goalLabels[g]).join(' · ')} · ${plan.minutes} minutes per strength session · ${plan.sets} set${plan.sets===1?'':'s'} per resistance movement</p><div class="grid"><div><h3>Strength · twice a week</h3><p class="small">${plan.strength.join(' · ')}</p></div><div><h3>Yoga → dance · daily</h3><p class="small">${plan.yoga.join(' · ')} → foot preparation → heels fundamentals → optional advanced focus.</p></div><div><h3>Cardio · twice a week</h3><p class="small">${plan.cardioMinutes} minutes per session. Your selected weekdays stay the same.</p></div></div><ul class="small">${plan.why.map(w=>`<li>${w}</li>`).join('')}</ul><p class="small muted">This replaces the selected strength exercises and yoga block when you apply it. Your workout history, weekdays, and dance preferences stay saved.</p>`;}
function renderGoals(){const p=state.profile;for(const g of Object.keys(goalLabels))$('#goal-'+g).checked=p.goals.includes(g);$('#primaryGoal').value=p.primary;$('#profileMinutes').value=p.minutes;$('#profileIntensity').value=p.intensity;$('#profileEquipment').value=p.equipment;$('#profileFloor').checked=p.floor;$('#profileCardio').value=p.cardioMinutes;$('#goalSummary').textContent=p.goals.map(g=>goalLabels[g]).join(' · ');$('#goalMode').textContent=state.customRoutine?'Custom strength selection; your goals still guide yoga.':'Recommended plan for your selected goals';previewGoals();$('#checkinHistory').replaceChildren();if(!state.checkins.length)$('#checkinHistory').textContent='Your check-ins will appear here. Start with how movement feels today.';else [...state.checkins].reverse().slice(0,8).forEach(c=>{const row=document.createElement('p');row.className='small';row.textContent=new Date(c.at).toLocaleDateString()+' · Mobility ease '+c.mobility+'/5 · Posture comfort '+c.posture+'/5 · Resistance: '+(c.load||'not recorded');$('#checkinHistory').append(row)});}

const plans=[{title:'Glutes & core',desc:'Steady movement for your lower body and core.',ids:[0,1,2,3,4],tag:'STRENGTH',color:'#edf1df'},{title:'Chest & posture',desc:'Build upper-body strength and practice upright posture.',ids:[5,7],tag:'UPPER BODY',color:'#f0e6dd'},{title:'Gentle recovery',desc:'A lighter day for easy movement and a fresh start.',ids:[8,9],tag:'RECOVERY',color:'#e3ecea'}];let selected=0,active=null,step=0,restEnd=null,ticker=null,startTime=0;

const oldStarter=['Glute bridge','Chair squat','Donkey kick','Fire hydrant','Reverse lunge','Hip thrust','Wall push-up','Shoulder-blade squeeze','Heel slide','Bird dog','Child’s pose','Thread the needle','Cat–cow'];
const starterNames=['Dumbbell floor press','Band or dumbbell row','Glute bridge','Chair squat','Band Pallof press','Heel slide','Biceps curl','Triceps kickback'];
if(!state.strengthV3){if(!state.routine||JSON.stringify(state.routine)===JSON.stringify(oldStarter))state.routine=[...starterNames];state.strengthV3=true;state.equipment='weights';state.goal=2;}
if(!state.cardioDays)state.cardioDays=[2,5];
if(!Array.isArray(state.routine))state.routine=[...starterNames];
state.routine=[...new Set(state.routine)].filter(n=>moves.some(x=>x[0]===n));

if(!state.profileMigrated){const priorDefault=['Dumbbell floor press','Band or dumbbell row','Glute bridge','Chair squat','Band Pallof press','Heel slide','Biceps curl','Triceps kickback'];if(JSON.stringify(state.routine)===JSON.stringify(priorDefault)){state.routine=goalPlan(state.profile).strength;state.profileApplied=true;state.customRoutine=false}else state.customRoutine=true;state.profileMigrated=true;}

function routineIds(){return state.routine.map(n=>moves.findIndex(x=>x[0]===n)).filter(i=>i>=0)}
plans.push({title:'Full-body resistance',desc:'Chest, glutes, abs, and arms with resistance bands or light weights. Repeat on your two strength days.',ids:[],tag:'FORMA 3.0',color:'#e4eadb'});selected=3;

const dailyFundamentals=['Heels alignment reset','Bevel and balance','Controlled weight transfer','Heels walk and stop','Arm lines and shoulder release','Small body roll','Pose and expression'];
const dailyYoga=['Cat–cow','Thread the needle','Child’s pose','Low lunge','Butterfly pose','Easy seat / lotus option'];
const advancedByDay=['Two-phrase performance rehearsal','Quarter-turn to pose','Layered arms and walking','Musicality: slow and accented','Body roll into a walk','Diagonal pathway changes','Floor-to-standing transition study'];
function idFor(name){return moves.findIndex(x=>x[0]===name)}
function dailyIds(day=new Date().getDay()){const names=[...(!state.dailyHeels.yogaOutside?goalYogaNames():[]),'Seated ankle pumps','Ankle circles',...dailyFundamentals,...(state.dailyHeels.advanced?[(state.profile.floor===false&&day===6)?'Two-phrase performance rehearsal':advancedByDay[day]]:[])];return [...new Set(names)].map(idFor).filter(i=>i>=0)}
function dailyPhase(id){const x=moves[id];return x[1]==='Yoga & mobility'?'1 · Yoga':x[1]==='Heels preparation'||x[0]==='Seated ankle pumps'?'2 · Foot and ankle preparation':x[1]==='Heels advanced'?'4 · Optional advanced extension':'3 · Heels fundamentals'}
plans.push({title:'Daily yoga → heels',desc:'Yoga first, then foot preparation, heels fundamentals, and today’s optional advanced drill.',ids:[],tag:'EVERY DAY',color:'#efe1df'});
plans.push({title:'Low-impact cardio',desc:'Easy walk, active step-touch, then a gentle march; duration follows your goal profile.',ids:[8,idFor('Low-impact cardio step-touch'),idFor('Easy cardio march')],tag:'TWICE A WEEK',color:'#e6e7f2'});
function renderHeels(){const day=new Date().getDay();$('#dailyFocus').textContent=state.profile.floor===false&&day===6?'Two-phrase performance rehearsal':advancedByDay[day];$('#yogaOutside').checked=state.dailyHeels.yogaOutside;$('#advancedDaily').checked=state.dailyHeels.advanced;$('#footwear').value=state.dailyHeels.footwear;$('#dailySequence').innerHTML=dailyIds(day).map(id=>`<div class="session-item row"><div><span class="category">${dailyPhase(id)}</span><p style="margin:6px 0">${moves[id][0]}</p><span class="small muted">${moves[id][2]}</span></div><button class="secondary" data-guide="${id}">Guide</button></div>`).join('');$('#danceWeek').innerHTML=[1,2,3,4,5,6,0].map(day=>`<div class="card"><span class="category">${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][day]}</span><h3>${advancedByDay[day]}</h3><p class="small">After yoga + fundamentals. Optional; use the easier version when needed.</p></div>`).join('');const m=monday();const days=new Set(state.sessions.filter(s=>s.kind==='daily_yoga_heels'&&new Date(s.at)>=m).map(s=>s.day));$('#dailyCount').textContent=days.size+' / 7 days completed';}


function renderWeeklyOverview(){const labels=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];$('#weeklyOverview').innerHTML=[1,2,3,4,5,6,0].map(day=>`<article class="card"><span class="category">${labels[day]}</span><h3>Yoga + dance</h3><p class="small">Yoga first, then heels fundamentals and an optional advanced drill.</p>${state.days.includes(day)?'<strong class="small">+ Chest · glutes · abs · arms</strong><p class="small">'+({bodyweight:'Bodyweight',bands:'Resistance bands',weights:'Light weights',both:'Bands + light weights'}[state.profile.equipment])+'</p>':''}${state.cardioDays.includes(day)?'<strong class="small">+ Cardio</strong><p class="small">'+state.profile.cardioMinutes+' minutes of low-impact movement</p>':''}${!state.days.includes(day)&&!state.cardioDays.includes(day)?'<span class="small muted">Lighter practice day</span>':''}</article>`).join('');const m=monday();const week=state.sessions.filter(s=>new Date(s.at)>=m);$('#weeklyStrength').textContent=week.filter(s=>!s.kind||s.kind==='strength').length+' / 2 strength';$('#weeklyCardio').textContent=week.filter(s=>s.kind==='cardio').length+' / 2 cardio';$('#weeklyDance').textContent=new Set(week.filter(s=>s.kind==='daily_yoga_heels').map(s=>s.day)).size+' / 7 yoga + dance days';$('#cardioOne').value=state.cardioDays[0];$('#cardioTwo').value=state.cardioDays[1];}

function renderSchedule(){const days=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];$('#scheduleDays').textContent=state.days.map(i=>days[i]).join(' + ');$('#routineCount').textContent=state.routine.length+' unique exercises · 2 sessions/week';$('#dayOne').value=state.days[0];$('#dayTwo').value=state.days[1];$('#routineList').innerHTML=moves.map((x,i)=>x[1].startsWith('Heels')||x[1]==='Cardio'||x[1]==='Yoga & mobility'?'':`<label class="routine-option"><input type="checkbox" data-routine="${i}" ${state.routine.includes(x[0])?'checked':''}><span><strong>${x[0]}</strong><small>${x[1]} · ${x[6]?'Optional advanced practice':x[2]}</small></span></label>`).join('');}

function illustration(type){let paths={bridge:'M15 48 L32 48 L48 26 L63 48 L73 48 M32 48 L24 34',squat:'M43 17 L43 34 L26 43 L43 58 M43 34 L62 34 M50 45 L70 45 L70 62',standing:'M41 22 L41 43 L28 61 M41 43 L60 56 M41 30 L25 40 M41 30 L58 26',floor:'M15 48 L41 48 L51 32 L65 48 L76 48',bird:'M25 32 L53 32 L72 18 M53 32 L53 55 M25 32 L24 55 M25 32 L8 20',wall:'M70 10 L70 62 M40 25 L57 32 L70 25 M40 25 L24 58 M39 28 L70 35',row:'M41 24 L28 40 L43 59 M28 40 L16 59 M41 28 L56 43 L48 46'};return `<div class="illustration"><svg viewBox="0 0 85 70" role="img" aria-label="Simplified exercise position"><path d="M5 63H80" stroke="#c6d0b2" fill="none"/><circle cx="${type==='bridge'||type==='floor'?12:40}" cy="${type==='bridge'||type==='floor'?44:13}" r="6" fill="#91aa66"/><path d="${paths[type]||paths.standing}" stroke="#365548" stroke-width="4" stroke-linecap="round" stroke-linejoin="round" fill="none"/></svg></div>`}
function localDate(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}function monday(){let d=new Date();d.setDate(d.getDate()-(d.getDay()+6)%7);d.setHours(0,0,0,0);return d}function plannedIds(i){if(i===4)return dailyIds();if(i===3)return routineIds();let ids=[...plans[i].ids];if(i===1&&state.equipment==='weights')ids.splice(1,0,6);if(state.duration===15&&i===0)ids=ids.slice(0,3);return ids}function prescription(id){if(active?.kind==='cardio'){if(id===8)return '5 easy minutes · warm up';if(moves[id][0]==='Easy cardio march')return '5 easy minutes · finish';return Math.max(5,state.profile.cardioMinutes-10)+' minutes · active step-touch'}return moves[id][2].replace('2 sets',goalPlan(state.profile).sets+' set'+(goalPlan(state.profile).sets===1?'':'s'))}
function render(){const m=monday();const w=state.sessions.filter(s=>(!s.kind||s.kind==='strength')&&new Date(s.at)>=m);$('#date').textContent=new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'});$('#greeting').textContent=`${state.name}, make a little room for yourself today.`;$('#total').textContent=state.sessions.length;$('#minutes').textContent=state.sessions.reduce((n,s)=>n+s.minutes,0);$('#goalStat').textContent=state.goal+' sessions';$('#weekCount').textContent=w.length+' / '+state.goal+' sessions';$('#weekBar').style.width=Math.min(100,w.length/state.goal*100)+'%';$('#week').innerHTML=Array.from({length:7},(_,i)=>{const d=new Date(m);d.setDate(m.getDate()+i);const done=w.some(s=>s.day===localDate(d));return `<div class="day ${done?'done':''}">${['M','T','W','T','F','S','S'][i]}<span>${done?'✓':d.getDate()}</span></div>`}).join('');$('#focus').innerHTML=plans.map((p,i)=>`<article class="card" style="background:${p.color}"><span class="category">${p.tag}</span><h2>${p.title}</h2><p class="small">${p.desc}</p><button class="secondary" data-plan="${i}">Choose session ↗</button></article>`).join('');$('#workoutTitle').textContent=plans[selected].title;$('#workoutDescription').textContent=plans[selected].desc;$('#workoutMeta').textContent=`${selected===5?state.profile.cardioMinutes+' min cardio':selected===4?'~20–25 min practice':selected===3?'Self-paced':selected===2?'10–15':state.duration+' min'} · ${plannedIds(selected).length} exercises · ${selected===3?({bodyweight:'Bodyweight',bands:'Resistance bands',weights:'Light weights',both:'Bands + light weights'}[state.profile.equipment]):selected===5?'Comfortable walking shoes':selected===4?(state.dailyHeels.footwear==='flats'?'Flats / comfortable shoes':'Supportive dance heels'):state.equipment==='weights'&&selected===1?'Light resistance':'Bodyweight'}`;renderLibrary();renderSchedule();renderHeels();renderWeeklyOverview();renderGoals();$('#history').replaceChildren();if(!state.sessions.length)$('#history').innerHTML='<div class="empty">Your first session starts the story. Completed workouts will appear here.</div>';else [...state.sessions].reverse().forEach(s=>{let el=document.createElement('div');el.className='session-item row';let a=document.createElement('strong');a.textContent=s.title;let b=document.createElement('span');b.className='small muted';b.textContent=new Date(s.at).toLocaleDateString()+' · '+s.minutes+' min · '+s.exercises+' exercises';el.append(a,b);$('#history').append(el)});for(const k of ['name','goal','duration','equipment'])$('#'+k).value=state[k]}
function renderLibrary(){const f=$('#filter').value;$('#exercises').innerHTML=moves.map((e,i)=>f==='all'||e[1]===f?`<article class="card"><span class="category">${e[1]}${e[6]?' · OPTIONAL ADVANCED':''}</span><div class="exercise">${illustration(e[5])}<div><strong>${e[0]}</strong><p class="small">${e[2]}</p></div></div><button class="secondary" data-guide="${i}">See form guide</button>${videoLink(i)}</article>`:'').join('')}
function showPage(p){for(const s of ['today','library','progress','settings','schedule','heels'])$('#'+s).classList.toggle('hidden',s!==p);document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===p))}document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page)showPage(b.dataset.page);if(b.dataset.plan!==undefined){selected=Number(b.dataset.plan);render();showPage('today');window.scrollTo({top:0,behavior:'smooth'})}if(b.dataset.guide!==undefined){const x=moves[Number(b.dataset.guide)];$('#guideContent').innerHTML=`<span class="eyebrow">${x[1]}</span><h2>${x[0]}</h2>${illustration(x[5])}<p>${x[3]}</p><p class="small">Easier option: ${x[4]}</p>${x[8]?`<p class="small muted">Variations: ${x[8]}</p>`:''}<p class="small muted">${x[2]} · Illustration is a simplified position, not an animation.</p>${videoLink(Number(b.dataset.guide))}`;$('#guide').showModal()}});
function stopTimer(){clearInterval(ticker);ticker=null;restEnd=null;$('#clock').textContent='0:45';$('#rest').textContent='Start 45s rest'}function showStep(){stopTimer();let id=active.ids[step],x=moves[id];$('#sessionStep').textContent=`${active.kind==='daily_yoga_heels'?dailyPhase(id)+' · ':''}EXERCISE ${step+1} OF ${active.ids.length}`;$('#sessionTitle').textContent=x[0];$('#sessionExercise').innerHTML=`<div class="exercise">${illustration(x[5])}<strong>${prescription(id)}</strong></div>${videoLink(id)}<p>${x[3]}</p><p class="small muted">Easier option: ${x[4]}</p>${active.kind==='daily_yoga_heels'?'<p class="small muted">Keep this a short skill practice. Flats are fine. If you feel pain, instability, or fatigue, use the easier option or finish early.</p>':''}`;$('#next').textContent=step===active.ids.length-1?'Finish workout ✓':'Next exercise →'}$('#start').onclick=()=>{if(!plannedIds(selected).length){toast('Choose at least one exercise in Weekly routine.');showPage('schedule');return}active={title:plans[selected].title,ids:plannedIds(selected),kind:selected===4?'daily_yoga_heels':selected===5?'cardio':'strength',yogaOutside:selected===4&&state.dailyHeels.yogaOutside};step=0;startTime=Date.now();showStep();$('#session').showModal();$('#skipDaily').classList.toggle('hidden',active.kind!=='daily_yoga_heels')};$('#next').onclick=()=>{if(!active)return;if(++step<active.ids.length)showStep();else{state.sessions.push({kind:active.kind,yogaOutside:active.yogaOutside,title:active.title,at:new Date().toISOString(),day:localDate(),minutes:Math.max(1,Math.round((Date.now()-startTime)/60000)),exercises:active.ids.length-(active.skipped||0),skipped:active.skipped||0});save();stopTimer();active=null;$('#session').close();render();toast(saved?'Workout saved. A little stronger today.':'Workout completed. Export to save a backup.')}};$('#close').onclick=()=>{if(confirm('End this session? Only finished workouts are saved.')){$('#session').close();stopTimer();active=null}};$('#session').addEventListener('cancel',()=>{stopTimer();active=null});$('#rest').onclick=()=>{if(ticker){stopTimer();return}restEnd=Date.now()+45000;$('#rest').textContent='Cancel rest';ticker=setInterval(()=>{const n=Math.max(0,Math.ceil((restEnd-Date.now())/1000));$('#clock').textContent='0:'+String(n).padStart(2,'0');if(n===0){stopTimer();$('#clock').textContent='Ready';toast('Rest complete. Continue when comfortable.')}},250)};$('#closeGuide').onclick=()=>$('#guide').close();$('#filter').onchange=renderLibrary;$('#settingsForm').onsubmit=e=>{e.preventDefault();state.name=$('#name').value.trim()||'You';state.goal=2;save();render();toast(saved?'Your plan is updated.':'Plan updated for this session only.')};$('#export').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='forma-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};render();

$('#routineForm').onsubmit=e=>{e.preventDefault();const a=Number($('#dayOne').value),b=Number($('#dayTwo').value);if(a===b){toast('Choose two different workout days.');return}let chosen=[...document.querySelectorAll('[data-routine]:checked')].map(c=>moves[Number(c.dataset.routine)][0]);if(!chosen.length){toast('Choose at least one exercise.');return}state.days=[a,b];state.routine=[...new Set(chosen)];state.customRoutine=true;state.goal=2;save();selected=3;render();toast(saved?'Your twice-weekly routine is saved.':'Routine updated for this visit only.');};
$('#startRoutine').onclick=()=>{selected=3;render();$('#start').onclick()};

$('#heelsSettings').onsubmit=e=>{e.preventDefault();state.dailyHeels={yogaOutside:$('#yogaOutside').checked,advanced:$('#advancedDaily').checked,footwear:$('#footwear').value};save();render();toast(saved?'Daily yoga → heels plan saved.':'Plan updated for this visit only.');};
$('#startDaily').onclick=()=>{selected=4;render();$('#start').onclick()};
$('#skipDaily').onclick=()=>{if(active&&active.kind==='daily_yoga_heels'){active.skipped=(active.skipped||0)+1;$('#next').onclick()}};

$('#cardioSettings').onsubmit=e=>{e.preventDefault();const a=Number($('#cardioOne').value),b=Number($('#cardioTwo').value);if(a===b){toast('Choose two different cardio days.');return}state.cardioDays=[a,b];save();render();toast(saved?'Cardio days saved.':'Cardio days updated for this visit only.');};
$('#startCardio').onclick=()=>{selected=5;render();$('#start').onclick()};

$('#goalsForm').onsubmit=e=>{e.preventDefault();const p=profileFromForm();if(!p.goals.length){toast('Choose at least one goal.');return}applyGoalPlan(p);};
$('#goalsForm').onchange=previewGoals;
$('#checkinForm').onsubmit=e=>{e.preventDefault();state.checkins.push({at:new Date().toISOString(),mobility:Number($('#checkMobility').value),posture:Number($('#checkPosture').value),load:$('#checkLoad').value.trim().slice(0,80)});save();render();toast(saved?'Check-in saved.':'Check-in saved for this visit only.');};
